#include <stdio.h>
#include <stdlib.h>

typedef struct Node { int data; struct Node *next; } Node;

Node *build(int *a, int n) {
    Node *head = NULL, *tail = NULL;
    for (int i = 0; i < n; i++) {
        Node *nd = malloc(sizeof(Node));
        nd->data = a[i]; nd->next = NULL;
        if (!head) head = tail = nd;
        else { tail->next = nd; tail = nd; }
    }
    return head;
}

/* 偶数长度时返回中间偏右 */
Node *midpoint(Node *head) {
    Node *slow = head, *fast = head;
    while (fast && fast->next) { slow = slow->next; fast = fast->next->next; }
    return slow;
}

int main(void) {
    int a[] = {1, 2, 3, 4, 5, 6};        /* 偶数个 */
    int b[] = {1, 2, 3, 4, 5};           /* 奇数个 */
    Node *la = build(a, 6), *lb = build(b, 5);
    printf("长度 6 的中点是 %d（中间偏右）\n", midpoint(la)->data);
    printf("长度 5 的中点是 %d（正中间）\n", midpoint(lb)->data);
    printf("说明：循环条件 while (fast && fast->next) 决定偶数时取右中点\n");
    return 0;
}
